SELECT count(*) FROM public.chartevents chartevents WHERE EXISTS (SELECT 1 FROM public.poe po WHERE po.hadm_id = chartevents.hadm_id AND po.order_provider_id = 'P57YCB') OR (EXISTS (SELECT 1 FROM public.icustays i, public.transfers t WHERE i.stay_id = chartevents.stay_id AND t.hadm_id = i.hadm_id AND t.careunit = i.first_careunit AND chartevents.charttime >= t.intime AND chartevents.charttime <= t.outtime) AND NOT EXISTS (SELECT 1 FROM public.diagnoses_icd d, public.d_icd_diagnoses dd WHERE d.hadm_id = chartevents.hadm_id AND d.icd_code = 'Z66' AND dd.icd_code = d.icd_code AND dd.icd_version = d.icd_version)) OR EXISTS (SELECT 1 FROM public.labevents l, public.d_labitems dl WHERE l.subject_id = chartevents.subject_id AND l.charttime = chartevents.charttime AND l.priority = 'STAT' AND l.flag = 'abnormal' AND dl.itemid = l.itemid AND dl.category = 'Chemistry');
